// World data for trips from any country: currencies, countries, departure cities, visa rules, holidays and fare estimates.
// Every JSON file here is a dated snapshot of a free source, regenerated by the tools/geo_*.mjs scripts (see each file's
// source/license fields). Pure functions only; the trip engine and UI both import from here.
const fx = require('./fx.json');
const countryData = require('./countries.json');
const cityData = require('./departureCities.json');
const visaData = require('./visaRules.json');
const holidayData = require('./holidays.json');
const indiaFestivals = require('../indiaHolidays.json');

const has = (object, key) => typeof key === 'string' && Object.prototype.hasOwnProperty.call(object, key);
const countries = countryData.countries;
const departureCities = cityData.cities;
const cityByName = new Map(departureCities.map((city) => [city.name, city]));

const isCountry = (code) => has(countries, code);
const isCurrency = (code) => has(fx.rates, code);
const countryName = (code) => (isCountry(code) ? countries[code].name : null);
/** Primary ISO-4217 currency of an ISO-3166 alpha-2 country, or null. */
const currencyForCountry = (code) => (isCountry(code) ? countries[code].currency : null);
const isSchengen = (code) => Boolean(isCountry(code) && countries[code].schengen);

/** Converts a whole amount between currencies through USD and rounds to an integer. Same currency returns the input untouched. */
function convert(amount, from, to) {
  if (from === to) return amount;
  if (!isCurrency(from) || !isCurrency(to)) throw new Error(`Unsupported currency conversion: ${from} to ${to}`);
  return Math.round((amount / fx.rates[from]) * fx.rates[to]);
}

/** Great-circle distance in km between two { lat, lon } points (haversine, mean Earth radius). */
function distanceKm(a, b) {
  const rad = (deg) => (deg * Math.PI) / 180;
  const dLat = rad(b.lat - a.lat); const dLon = rad(b.lon - a.lon);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLon / 2) ** 2;
  return 2 * 6371 * Math.asin(Math.min(1, Math.sqrt(h)));
}

// Return economy fare per traveller in USD by one-way great-circle distance. Mid-range estimates for booking a few weeks
// ahead, used only when the explicit Indian fare table (seeds.departureCities) has no entry. Upper bound is exclusive.
const FARE_BANDS_USD = [
  { maxKm: 150, usd: 40, label: 'Nearby: ground transport' },
  { maxKm: 800, usd: 160, label: 'Short haul (under 800 km)' },
  { maxKm: 2000, usd: 260, label: 'Short to medium haul (800 to 2,000 km)' },
  { maxKm: 3500, usd: 380, label: 'Medium haul (2,000 to 3,500 km)' },
  { maxKm: 5500, usd: 520, label: 'Medium to long haul (3,500 to 5,500 km)' },
  { maxKm: 8000, usd: 760, label: 'Long haul (5,500 to 8,000 km)' },
  { maxKm: 11000, usd: 1000, label: 'Very long haul (8,000 to 11,000 km)' },
  { maxKm: Infinity, usd: 1300, label: 'Ultra long haul (over 11,000 km)' },
];
const fareBand = (km) => FARE_BANDS_USD.find((band) => km < band.maxKm);

/**
 * Estimated return fare per traveller in USD from a departure point to a trip. Open jaw for routes: fly into `first`,
 * home from `last`; each leg costs half the return fare of its band.
 */
function estimateReturnFareUsd(from, first, last = first) {
  const outKm = distanceKm(from, first); const backKm = distanceKm(from, last);
  const out = fareBand(outKm); const back = fareBand(backKm);
  return { usd: Math.round((out.usd + back.usd) / 2), km: Math.round(Math.max(outKm, backKm)), label: out.usd >= back.usd ? out.label : back.label };
}

const departureCity = (name) => cityByName.get(name) || null;

/** Up to `count` departure cities for a home country: that country's cities first, then the nearest others. */
function citiesNear(homeCountry, count) {
  const home = departureCities.filter((city) => city.countryCode === homeCountry);
  const continent = isCountry(homeCountry) ? countries[homeCountry].continent : null;
  const anchor = home[0] || departureCities.find((city) => countries[city.countryCode]?.continent === continent) || departureCities[0];
  const rest = departureCities.filter((city) => city.countryCode !== homeCountry).sort((a, b) => distanceKm(anchor, a) - distanceKm(anchor, b));
  return [...home, ...rest].slice(0, count);
}

// Visa rules: see tools/geo_visa_rules.mjs for the one-character-per-destination encoding.
const visaIndex = Object.fromEntries(visaData.destinations.map((code, index) => [code, index]));
/** Entry rule for a passport visiting a country: { kind: 'home'|'free'|'voa'|'eta'|'evisa'|'required'|'noAdmission'|'unknown', days? }. */
function visaRule(passport, country) {
  if (passport && passport === country) return { kind: 'home' };
  const row = has(visaData.rules, passport) ? visaData.rules[passport] : null; const index = visaIndex[country];
  if (!row || index === undefined) return { kind: 'unknown' };
  const code = row[index];
  if (code >= 'a' && code <= 'q') return { kind: 'free', days: visaData.freeDays[code.charCodeAt(0) - 97] };
  return { kind: visaData.encoding[code] || 'unknown' };
}

// Days needed before departure to arrange entry. Unknown and no-admission are treated like a full visa (conservative).
const VISA_LEAD_DAYS = { home: 0, free: 0, voa: 0, eta: 3, evisa: 7, required: 30, noAdmission: 30, unknown: 30 };
const SCHENGEN_VISA_LEAD_DAYS = 45;
function visaLeadDays(passport, country) {
  const { kind } = visaRule(passport, country);
  return kind === 'required' && isSchengen(country) ? SCHENGEN_VISA_LEAD_DAYS : VISA_LEAD_DAYS[kind];
}

// Typical government entry fees per traveller in USD (visa, e-visa, ETA). A Schengen short-stay visa is EUR 90 plus service.
const ENTRY_FEE_USD = { home: 0, free: 0, voa: 35, eta: 25, evisa: 40, required: 160, noAdmission: 160, unknown: 160 };
const SCHENGEN_VISA_FEE_USD = 110;
function entryFeeUsd(passport, country) {
  const { kind } = visaRule(passport, country);
  return kind === 'required' && isSchengen(country) ? SCHENGEN_VISA_FEE_USD : ENTRY_FEE_USD[kind];
}

/** National public holidays for 2026-2027. India also merges the festival list in src/lib/indiaHolidays.json. */
function holidaysFor(countryCode) {
  const list = has(holidayData.countries, countryCode) ? holidayData.countries[countryCode] : [];
  if (countryCode !== 'IN') return list.map((item) => ({ ...item }));
  const seen = new Set(list.map((item) => item.date));
  return [...list, ...indiaFestivals.holidays.filter((item) => !seen.has(item.date))].map((item) => ({ ...item })).sort((a, b) => a.date.localeCompare(b.date));
}

const sources = Object.fromEntries([['fx', fx], ['countries', countryData], ['departureCities', cityData], ['visaRules', visaData], ['holidays', holidayData]]
  .map(([key, data]) => [key, { source: data.source, license: data.license, fetchedAt: data.fetchedAt, ...(data.attribution ? { attribution: data.attribution } : {}) }]));

module.exports = {
  fx, countries, departureCities, sources, FARE_BANDS_USD, VISA_LEAD_DAYS, SCHENGEN_VISA_LEAD_DAYS, ENTRY_FEE_USD,
  isCountry, isCurrency, countryName, currencyForCountry, isSchengen, convert, distanceKm, fareBand, estimateReturnFareUsd,
  departureCity, citiesNear, visaRule, visaLeadDays, entryFeeUsd, holidaysFor,
};
